// Z/2Z as the quotient of the integers by the ideal generated by 2
#include <iostream>
#include "../src/aerobus.h"

// 32 bits integers as Ring
using RING = aerobus::i32;

// Z/2Z as quotient ring
using FIELD = aerobus::Quotient<RING, RING::val<2>>;

int main() {
    // inject 2 in FIELD (Z/2Z as algebraic structure)
    using Y = FIELD::inject_constant_t<2>;

    // its canonical representative, as an int
    constexpr int y = Y::get<int>();

    // 2 == 0 in Z/2Z
    std::cout << "expected = 0" << std::endl;
    std::cout << "computed = " << y << std::endl;
    return y == 0 ? 0 : 1;
}
